using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1WildCheck {
 static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");static string Out=>Root+"/Docs/Review/2026-11-13_1F_WildernessDetail/";const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Run(){var scene=SceneManager.GetActiveScene();if(scene.isDirty||Application.isPlaying||!scene.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");var ts=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var map=ts.ToDictionary(t=>AnimationUtility.CalculateTransformPath(t,null));var before=JArray.Parse(File.ReadAllText(Out+"before_transforms.json"));var changes=new List<string>();int rotations=0;foreach(var b in before){string path=(string)b["path"];if(!map.TryGetValue(path,out var t)){changes.Add("Missing "+path);continue;}bool plant=path.StartsWith("1F_AbandonedFactory/WildernessEnding/DryScrubAndStone/")&&!path.Contains("Rock")&&t.GetComponent<MeshFilter>();foreach(var q in new[]{new{key="local",value=V(t.localPosition)},new{key="rotation",value=V(t.localEulerAngles)},new{key="scale",value=V(t.localScale)}}){var a=b[q.key].Values<float>().ToArray();if(!q.value.Where((v,i)=>Mathf.Abs(v-a[i])>.0001f).Any())continue;if(plant&&q.key=="rotation")rotations++;else changes.Add(path+" "+q.key);}if((bool)b["active"]!=t.gameObject.activeSelf)changes.Add(path+" active");if(!JToken.DeepEquals(JToken.FromObject(t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,c.enabled})),b["colliders"]))changes.Add(path+" colliders");}
 string temp=Path.Combine(Path.GetTempPath(),"AfterSeconds_WildernessDetail_20261113");var ground=new List<object>();foreach(string name in new[]{"AE_OvergrownFactoryTerrain","FW_WildernessTerrain"}){var t=GameObject.Find(name).GetComponent<Terrain>();var d=t.terrainData;using(var memory=new MemoryStream()){using(var w=new BinaryWriter(memory,System.Text.Encoding.UTF8,true)){foreach(float h in d.GetHeights(0,0,d.heightmapResolution,d.heightmapResolution))w.Write(h);}ground.Add(new{name,heightsUnchanged=memory.ToArray().SequenceEqual(File.ReadAllBytes(temp+"/"+name+".raw"))});}}
 var shader=AssetDatabase.LoadAssetAtPath<Shader>(E+"WDNaturalLit.shader");var messages=ShaderUtil.GetShaderMessages(shader).Select(m=>new{m.message,severity=m.severity.ToString(),m.line}).ToArray();object[] counts={0,0,0};typeof(Editor).Assembly.GetType("UnityEditor.LogEntries").GetMethod("GetCountsByType",BindingFlags.Public|BindingFlags.Static).Invoke(null,counts);
 var result=new{scene=scene.path,saved=!scene.isDirty,playing=Application.isPlaying,runInBackground=Application.runInBackground,beforeTransforms=before.Count,transforms=ts.Length,slopeAlignedExistingPlants=rotations,unexpectedTransformChanges=changes,colliders=ts.Sum(t=>t.GetComponents<Collider>().Length),terrainGround=ground,cameraFar=Camera.main.farClipPlane,shaderMessages=messages,missingMeshes=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh),missingMaterials=ts.SelectMany(t=>t.GetComponents<Renderer>()).Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader)),missingScripts=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),consoleErrors=(int)counts[0],consoleWarnings=(int)counts[1]};File.WriteAllText(Out+"final_check.json",JsonConvert.SerializeObject(result,Formatting.Indented));Selection.activeGameObject=GameObject.Find("WildernessEnding");SceneView.lastActiveSceneView?.LookAt(new Vector3(-145,6,-31.5f),Quaternion.LookRotation(new Vector3(-1,.063f,-.035f)),63,false,true);return result;}
}
